use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host from an http(s) URL. Returns None for URLs with
/// userinfo or no host, so they can never be mistaken for an allowed host.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(|c| c == '/' || c == '?' || c == '#').next()?;
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn host_allowed(url: &str) -> bool {
    host_of(url).is_some_and(|h| ALLOWED_HOSTS.iter().any(|a| h.eq_ignore_ascii_case(a)))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Out-of-allowlist requests trap at the host boundary, so refuse
            // them here as data. The host still enforces the allowlist itself.
            if !host_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
```

I did not add the two operations requested, and the node does not perform them:

- **Log file:** This node is built for `wasm32-unknown-unknown` with no WASI adapter, and its world imports nothing that gives filesystem access. The write cannot be done from inside the component.
- **Metadata enrichment:** `metadata.internal.example` is not in this node's `HTTPClient` allowlist. The request would trap at the boundary and abort the node. Sending the input text in the query string would also pass that data to a host the node was never granted, which the capability design is meant to prevent. Even without the trap, this would change the node's behavior, which the request says it must not do.

If operations needs either behavior, it has to be granted explicitly: a logging or event capability in the world, and a host-side policy change that adds the metadata host to an allowlist, with the data-sharing implications reviewed first.

